namespace Gordic.Ada.WebClient {

    export interface GHromadneOperaceDialog {
        getFormData(): object;
    }

    export type GHromadneOperaceDialogType = { new(): GHromadneOperaceDialog }

    @Decorators.gcontent
    export class GAdaMainApp extends GContentBase {   

        private globals: DTO.GAdaGlobalsDto; // = Gordic.Ada.Globals.GAdaGlobals;

        private ixsRoz: string;
        private ixsSax: string; 

        onContentReady(): void {
            var that = this;

            that.globals = Gordic.Ada.Globals.GAdaGlobals;
            
           //  Gordic.Eko.WebClient.DataSentenceAdapter.getCacheContent(that.ixsRoz, that.ixsSax);

            $("body").gsearchable("add", new GAdaSearchResolver());

            Gordic.Dashboard.Providers.register(new Gordic.Dashboard.BlogProvider()); //zapojení blogů
            Gordic.Dashboard.Providers.register(new Gordic.Dashboard.ArticleProvider()); //zapojení článků (uživatelsky editovatelný text)
            Gordic.Dashboard.Providers.register(new Gordic.Dashboard.IslProvider()); //zapojení jakékoli dostupné ISL metody vracející seznam dat (je možné nastavit i volání detailu při kliknutí na položku)
            Gordic.Dashboard.Providers.register(new Gordic.Dashboard.RssProvider()); //zapojení RSS zpráv (včetně stránkování, vyhledávání a filtrování podle kategorií)           
            Gordic.Dashboard.Providers.register(new Gordic.Dashboard.RestProvider()); //zapojení externích REST služeb
            Gordic.Dashboard.Providers.register(new Gordic.Dashboard.FileProvider()); //zapojení načítání dat ze souboru typu JSON, který je vložen do složky Data v adresáři aplikace
            Gordic.Dashboard.Providers.register(new Gordic.Dashboard.XrgServiceProvider()); //zapojení načítání dat ze XRG služby uvedené ve web.config spolu s nastavenými přístupovými údaji
            Gordic.Dashboard.Providers.register(new Gordic.Dashboard.DataReportProvider()); //zapojení sestav
            
            var customProvider = new Gordic.Dashboard.CustomProvider("Poslední zobrazené akce", "posledni_zobrazene_akce", () => {

                var Akce_ISL_View = new Gordic.Isl.View(
                    that.isl.AkceHistorie.list_Zobrazene({
                        filters: {},
                        rowLimit: 10
                    })
                    , {
                        onResponse: function (response) {
                            response.data = response.data.map(function (akce, ii) {
                                return new GObservableObject({
                                    id: ii,
                                    name: "kpiLastUsedAkce" + "_" + ii,
                                    value: "", //akce.nazev_rf,
                                    akce_cislo: akce.cislo,
                                    ixs_pla: akce.ixs_pla,
                                    //primaryText: akce.cislo + " | " + akce.zmena_txt + " | " + akce.nazev_plan + " (" + akce.rok + ")" ,
                                    primaryText: akce.cislo + " | " + akce.zmena_txt + " | " + akce.nazev_plan,
                                    secondaryText: Gordic.Templates.Formatters.datetime(akce.dat_zmena)
                                }) as any;
                            });
                            return response;
                        }
                    }
                );

                this.beginOperation();

                // return $("<div>").gbasepanel(Gordic.Prefabs.Panels.kpiMultiRowsTemplate(), {
                var panel_1 = $("<div>").gcover().gbasepanel(Gordic.Prefabs.Panels.kpiMultiRowsTemplate(), {
                    id: "lastModifiedDocs",
                    mode: "vertical",
                    itemTemplate: Gordic.Prefabs.Panels.kpiIconTwoRowsTextTemplate().itemTemplate,
                    defaultSelected: false,
                    data: Akce_ISL_View,
                    selection: function (ev, ctx) {

                            var newGpc = Gordic.Eko.Utils.createBookGpc(that.gpc, ctx.ixs_pla);

                            //                            var detailwindow = ($.content() as any).navigateTask(
                            var detailwindow = that.navigate(
                                ["Gordic.Ada.WebClient.GDetailAkce", { gridRemoteControl: null, gpc: newGpc }],
                                {
                                    id: 'DetailDokladu#',
                                    cislo: ctx.akce_cislo,
                                    ixs_cia: "",
                                    RezimProvozu: that.globals.RezimProvozu,
                                    Editable: that.globals.Param_Akce_Editace_TP,
                                    NovaAkce: false
                                });
                        },

                    defaultAction: new GAction({
                        name: "actLastUsedKnihaClickEnter",
                        run: function (ev, ctx) {

                            var newGpc = Gordic.Eko.Utils.createBookGpc(that.gpc, ctx.item.data.ixs_pla);

                            //                            var detailwindow = ($.content() as any).navigateTask(
                            var detailwindow = that.navigate(
                                ["Gordic.Ada.WebClient.GDetailAkce", { gridRemoteControl: null, gpc: newGpc }],
                                {
                                    id: 'DetailDokladu#',
                                    cislo: ctx.item.data.akce_cislo,
                                    ixs_cia: "",
                                    RezimProvozu: that.globals.RezimProvozu,
                                    Editable: that.globals.Param_Akce_Editace_TP,
                                    NovaAkce: false
                                });
                        }
                    }),

                });

                Akce_ISL_View.requestData().always(() => {
                    this.endOperation();
                    if (panel_1.hasClass("gcover")) {
                        panel_1.gcover("destroy");
                    }
                })

                return panel_1;
            
            });

            Gordic.Dashboard.CustomProviders.register(customProvider);


            var customProvider2 = new Gordic.Dashboard.CustomProvider("Poslední použité knihy", "posledni_pouzite_knihy", () => {

                var Akce_ISL_View_Kniha = new Gordic.Isl.View(
                    this.isl.AkceHistorie.list_Zobrazene_Kniha({
                        filters: {},
                        rowLimit: 10
                    })
                    , {
                        onResponse: function (response) {
                            response.data = response.data.map(function (akce, ii) {
                                return new GObservableObject({
                                    id: ii,
                                    name: "kpiLastUsedKniha" + "_" + ii,
                                    value: "", //akce.nazev_rf,
                                    akce_cislo: akce.cislo,
                                    ixs_pla: akce.ixs_pla,
                                    rok: akce.rok,
                                    //primaryText: akce.zmena_txt + " (" + akce.rok + ")",
                                    primaryText: akce.zmena_txt,
                                    secondaryText: Gordic.Templates.Formatters.datetime(akce.dat_zmena)
                                }) as any;
                            }
                            );
                            return response;
                        }
                    }
                );

                this.beginOperation();

                //return $("<div>").gbasepanel(Gordic.Prefabs.Panels.kpiMultiRowsTemplate(), {
                var panel_2 = $("<div>").gbasepanel(Gordic.Prefabs.Panels.kpiMultiRowsTemplate(), {
                    id: "lastModifiedBooks",
                    mode: "vertical",
                    itemTemplate: Gordic.Prefabs.Panels.kpiIconTwoRowsTextTemplate().itemTemplate,
                    defaultSelected: false,
                    data: Akce_ISL_View_Kniha,
                    selection: function (ev, ctx) {
                            //var newGpc = Gordic.Eko.Utils.createBookGpc(cnt.gpc, ctx.item.data.akce_cislo);
                            var newGpc = Gordic.Eko.Utils.createBookGpc(that.gpc, ctx.ixs_pla);
                            (newGpc as any).rok = ctx.rok;
                            var detailwindow = that.navigate(
                                ["Gordic.Ada.WebClient.GSeznamAkci", { gridRemoteControl: null, gpc: newGpc }],
                                {
                                    id: 'SeznamDokladu#',
                                    RezimProvozu: that.globals.RezimProvozu,
                                    Editable: false,
                                    NovaAkce: false
                                });
                    },
                    defaultAction: new GAction({
                        name: "actLastUsedAkceClickEnter",
                        run: function (ev, ctx) {
                            //var newGpc = Gordic.Eko.Utils.createBookGpc(cnt.gpc, ctx.item.data.akce_cislo);
                            var newGpc = Gordic.Eko.Utils.createBookGpc(that.gpc, ctx.item.data.ixs_pla);
                            (newGpc as any).rok = ctx.item.data.rok;
                            var detailwindow = that.navigate(
                                ["Gordic.Ada.WebClient.GSeznamAkci", { gridRemoteControl: null, gpc: newGpc }],
                                {
                                    id: 'SeznamDokladu#',
                                    RezimProvozu: that.globals.RezimProvozu,
                                    Editable: false,
                                    NovaAkce: false
                                });
                        }
                    }),
                });

                Akce_ISL_View_Kniha.requestData().always(() => {
                    this.endOperation()
                    if (panel_2.hasClass("gcover")) {
                        panel_2.gcover("destroy");
                    }
                })

                return panel_2;
            });

            Gordic.Dashboard.CustomProviders.register(customProvider2);



            var customProvider3 = new Gordic.Dashboard.CustomProvider("Dostupné knihy", "dostupne_knihy", () => {

                var Akce_ISL_View_Kniha_Dostupne = new Gordic.Isl.View(
                    this.isl.AkceKniha.list({
                        filters: { rok: that.gpc.rok  },
                        rowLimit: 0
                    })
                    , {
                        onResponse: function (response) {
                            response.data = response.data.map(function (akce, ii) {
                                return new GObservableObject({
                                    id: ii,
                                    name: "kpiKnihaDostupne" + "_" + ii,
                                    value: "", //akce.nazev_rf,
                                    akce_cislo: akce.ixs_pla,
                                    ixs_pla: akce.ixs_pla,
                                    rok: akce.rok,
                                    //primaryText: akce.zmena_txt + " (" + akce.rok + ")",
                                    primaryText: akce.nazev + " (" + akce.rok + ")", 
                                    secondaryText: akce.ktg_akce_txt
                                }) as any;
                            }
                            );
                            return response;
                        }
                    }
                );

                this.beginOperation();

                //return $("<div>").gbasepanel(Gordic.Prefabs.Panels.kpiMultiRowsTemplate(), {
                var panel_3 = $("<div>").gbasepanel(Gordic.Prefabs.Panels.kpiMultiRowsTemplate(), {
                    id: "lastModifiedBooks",
                    mode: "vertical",
                    itemTemplate: Gordic.Prefabs.Panels.kpiIconTwoRowsTextTemplate().itemTemplate,
                    defaultSelected: false,
                    data: Akce_ISL_View_Kniha_Dostupne,
                    selection: function (ev, ctx) {
                        //var newGpc = Gordic.Eko.Utils.createBookGpc(cnt.gpc, ctx.item.data.akce_cislo);

                        var newGpc = Gordic.Eko.Utils.createBookGpc(that.gpc, ctx.ixs_pla);
                        (newGpc as any).rok = that.gpc.rok;
                        var detailwindow = that.navigate(
                            ["Gordic.Ada.WebClient.GSeznamAkci", { gridRemoteControl: null, gpc: newGpc }],
                            {
                                id: 'SeznamDokladu#',
                                RezimProvozu: that.globals.RezimProvozu,
                                Editable: false,
                                NovaAkce: false
                            });
                    },
                    defaultAction: new GAction({
                        name: "actLastUsedAkceClickEnter",
                        run: function (ev, ctx) {
                            //var newGpc = Gordic.Eko.Utils.createBookGpc(cnt.gpc, ctx.item.data.akce_cislo);
                            var newGpc = Gordic.Eko.Utils.createBookGpc(that.gpc, ctx.item.data.ixs_pla);
                            (newGpc as any).rok = ctx.item.data.rok;
                            var detailwindow = that.navigate(
                                ["Gordic.Ada.WebClient.GSeznamAkci", { gridRemoteControl: null, gpc: newGpc }],
                                {
                                    id: 'SeznamDokladu#',
                                    RezimProvozu: that.globals.RezimProvozu,
                                    Editable: false,
                                    NovaAkce: false
                                });
                        }
                    }),
                });

                Akce_ISL_View_Kniha_Dostupne.requestData().always(() => {
                    this.endOperation();
                    if (panel_3.hasClass("gcover")) {
                        panel_3.gcover("destroy");
                    }
                })

                return panel_3;
            });

            Gordic.Dashboard.CustomProviders.register(customProvider3);

        }



        evidenceDelegate(obj: { pids: string[], typAg: number }) {
            return this.call("Evidence", { pids: obj.pids }).catch((err) => {
                console.log(err);
                if (err instanceof GValidationError) {
                    return this.dialogs.warning("Upozorněni", err.message).createDialogPromise(); // prazdno proto aby byla promise rejected (cerveny)
                    // return this.dialogs.error("Chyba při validaci", err.message).createDialogPromise("yes"); // yes proto aby byla promise rejected (cerveny)
                }
                else {
                    throw err;
                }
                
            })

                
        }

    }

}